using namespace std;

vector<long long> threeLargestProducts(vector<long long>& a) {
    // Write your solution here
    return vector<long long>(a.size(), -1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<long long> res = threeLargestProducts(a);
    for (size_t i = 0; i < res.size(); i++) cout << res[i] << (i + 1 < res.size() ? ' ' : '\n');
    return 0;
}

